// Validate incoming request for PDF generation
const report = event.body?.final_report;

if (!report) {
  throw new Error("Missing required field: final_report");
}

return { report };

// Normalization utility
function norm(v) {
  if (!v) return v;
  if (typeof v === "string") return v.normalize("NFKC").trim();
  return v;
}

const r = steps.validate_payload.report;

return {
  risks: Array.isArray(r.risks) ? r.risks : [],
  themes: Array.isArray(r.themes) ? r.themes : [],
  mitigations: Array.isArray(r.mitigations) ? r.mitigations : [],
  summary: norm(r.summary),
  meta: {
    project_title: norm(r.meta?.project_title) || "PreMortem AI Report",
    generated_at: r.meta?.generated_at || new Date().toISOString(),
    workflow_run_id: r.meta?.workflow_run_id || null
  }
};

// Return final PDF export output
return {
  status: "pdf_generated",
  pdf_base64: steps.generate_pdf.pdf_base64,
  filename: steps.generate_pdf.filename || "premortem_report.pdf",
  meta: steps.normalize_report.meta
};
